  cylinder: {
    length: TOWER_H,
    bottomRadius: 52.0,
    topRadius: 6.0,
    material: Cesium.Color.GOLD.withAlpha(0.92),
    outline: true,
    outlineColor: Cesium.Color.DARKGOLDENROD,
    numberOfVerticalLines: 16
  }
});

// Antenna spire above the main cylinder
viewer.entities.add({
  position: Cesium.Cartesian3.fromDegrees(LON, LAT, TOWER_H + 22),
  cylinder: {
    length: 44,
    bottomRadius: 5.5,
    topRadius: 0.4,
    material: Cesium.Color.fromCssColorString('#aaaaaa').withAlpha(0.95),
