// --- Camera: classic Trocadéro-side angle ---
// heading 180 → camera is north of the tower, faces south
// pitch -22 → gentle downward look, tourist-photo feel
// target at 80 m (≈ lower quarter) so the full shaft is visible above
// range 1100 m gives city-map context in the foreground
const lookTarget = Cesium.Cartesian3.fromDegrees(LON, LAT, 80.0);
viewer.camera.lookAt(
